update sc_plans set spec=jsonb_set(spec,'{shots}',coalesce(spec->'shots','[]'::jsonb) || $q$[{"n": 1, "id": "du1_share", "vid": "duv1_share", "img_prompt": "BOY (years ago): a Korean boy about eight, round face, short black hair, navy hoodie, red backpack. PUPPY: a small soaked golden-yellow Korean village puppy (nureongi) with floppy ears. UMBRELLA: a child's bright yellow umbrella with one small white heart hand-painted on one panel. PLACE: the gate of a small countryside elementary school: two plain stone gateposts, a short covered entrance with a tiled roof, a muddy village road with rice paddies behind, autumn rain. Years ago, autumn rain at the school gate. The boy crouches beside the stone gatepost and tilts his yellow umbrella over a shivering soaked puppy, so the rain falls on his own back instead; the white heart on the umbrella is visible. Slightly faded colors like an old memory. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": [], "reuse": null, "action": "Rain falls on the boy's back as he keeps the umbrella over the puppy; the puppy looks up and wags its tail slowly.", "dur": 5, "cap": "He shared his umbrella with a stray.", "detail": "하트 그린 노란 우산"}, {"n": 2, "id": "du2_road", "vid": "duv2_road", "img_prompt": "OLD DOG: the same golden-yellow nureongi now old and big, a grey-white muzzle, slightly cloudy eyes, a faded red collar. UMBRELLA: a child's bright yellow umbrella with one small white heart hand-painted on one panel. Many years later, autumn rain on the muddy village road. The old dog walks slowly carrying the folded yellow umbrella with the white heart in its mouth, its cloudy eyes half closed; Kachi flies just ahead of its nose at eye level, guiding it along the road toward the school gate in the distance. The magpie is exactly the character in the magpie reference image: a small round chibi magpie with a glossy black head, cream-white face and belly, big shiny dark-brown eyes, short black beak, dark navy-blue wings, a red knotted neckerchief and a small brown leather satchel. It does NOT hold a microphone. Style: handcrafted 3D miniature diorama photographed with a macro lens, tilt-shift, shallow depth of field, soft cinematic light, felt, clay, paper and wood textures with tiny hand-painted details, gentle film grain, warm nostalgic color grade, clay figurines with soft rounded faces and deeply emotional Pixar-like expressions, not photorealistic. Vertical 9:16 frame, main subject in the middle of the frame, a calm uncluttered area in the top fifth of the frame. Absolutely no text, no letters, no numbers, no hangul, no logos, no labels, no brand names, no watermark anywhere.", "refs": ["social/side/gen/c1_magpie.jpeg"], "reuse": null, "action": "Kachi flutters slowly just ahead; the old dog takes one careful step after it, the umbrella in its mouth.", "dur": 5, "cap": "Years later, he still brought it.", "detail": "늙은 개의 흐린 눈 — 까치가 길을 이끈다"}]$q$::jsonb) where id='P261030-dog-umbrella'